head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf76210";
scwin.editor = undefined;
scwin.upload = undefined;

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — pageContext.ldMktTpCd, pageContext.usrTpCd

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_ldMktTpCd", fn: function(){ return ((dma_pageContext.get("ldMktTpCd") ?? "") === '1' || (dma_pageContext.get("usrTpCd") ?? "") === '1'); } }, { id: "if_ldMktTpCd_2", fn: function(){ return ((dma_pageContext.get("ldMktTpCd") ?? "") === '2' || (dma_pageContext.get("usrTpCd") ?? "") === '1'); } }, { id: "if_ldMktTpCd_3", fn: function(){ return ((dma_pageContext.get("ldMktTpCd") ?? "") === '6' || (dma_pageContext.get("usrTpCd") ?? "") === '1'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

// [A] 초기 목록 미해결 — jldstf76210: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.editor =new Dext5editor("dext5editor1"); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf76210' }); }

try { scwin.upload =new Dext5Upload("dext5upload"); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf76210' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf76210.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name input_47_onclick
 * @description 「상위법규검색」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.input_47_onclick = function(e){
    try {
        scwin.openUpLawPop()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf76210.input_47_onclick' }); }
};

/**
 * @method
 * @name input_49_onclick
 * @description 「삭제」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.input_49_onclick = function(e){
    try {
        scwin.delValue()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf76210.input_49_onclick' }); }
};

/**
 * @method
 * @name btn_reg_onclick
 * @description 「등록」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_reg_onclick = async function(e){
    try {
        await scwin.reg()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf76210.btn_reg_onclick' }); }
};

/**
 * @method
 * @name btn_frame_onclick
 * @description 「닫기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_frame_onclick = function(e){
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.CloseFrame
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf76210.btn_frame_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name reg
 * @description reg 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.reg = async function () {
    const sprtRoomtitle = $c.util.getComponent('ipt_sprtRoomtitle').getValue();
    if ($.trim(sprtRoomtitle).length === 0) {
        await $c.win.alert("제목을 입력해 주세요.");
        ($c.util.getComponent('ipt_sprtRoomtitle') && $c.util.getComponent('ipt_sprtRoomtitle').setFocus ? $c.util.getComponent('ipt_sprtRoomtitle').setFocus() : $c.util.getComponent('ipt_sprtRoomtitle').focus());
        return;
    }
    scwin.transfer();
};

/**
 * @method
 * @name transfer
 * @description transfer 처리
 * @returns {void}
 * @hidden N
 */
scwin.transfer = function () {
    DEXT5UPLOAD.Transfer("dext5upload");
};

/**
 * @method
 * @name DEXT5UPLOAD_OnTransfer_Complete
 * @description DEXT5 UPLOAD On Transfer Complete 처리
 * @param {String} dextId dextId
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.DEXT5UPLOAD_OnTransfer_Complete = async function (dextId) {
    const textNew = DEXT5UPLOAD.GetNewUploadListForText("dext5upload");
    if (textNew != null) {
        const rtn = fn_newTextToString(textNew);  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_newTextToString — 타 모듈 as-is 공통(stf/ods·ins/hindr) — 반입 범위 밖
        $('#ipt_attachFileInfo', $('#regForm')).val(rtn);
    }
    $('#ipt_SCREN_ID', $('#regForm')).val("/jldstf76210/jldstf76210.xml");
    $('#ipt_method', $('#regForm')).val("regSprtRoom");
    const htmlText = DEXT5.getBodyValue("dext5editor1");
    $c.util.getComponent('ipt_sprtRoomContn').setValue(htmlText);
    const notHtmlText = DEXT5.getBodyTextValue("dext5editor1");
    $c.util.getComponent('ipt_sprtRoomContnNoHtml').setValue(notHtmlText);
    if (await $c.win.confirm("저장하시겠습니까?")) {
        $('#regForm').submit();
    }
};

/**
 * @method
 * @name openUpLawPop
 * @description open Up Law Pop 처리
 * @returns {void}
 * @hidden N
 */
scwin.openUpLawPop = function () {
    const url = "/ods/sprtroom.do?method=readRelatedLawList&mode=popup&SCREN_ID=JLDODS76230.jsp&SCREN_PROCES_TP_CD=01";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    $c.win.openPopup((function (__u) { const __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(url), { id: "popup", type: "pageFramePopup", title: "상위법규목록", width: "600px", height: "700px" }, {});
};

/**
 * @method
 * @name setData
 * @description set Data 처리
 * @param {*} tit tit
 * @param {*} no no
 * @returns {void}
 * @hidden N
 */
scwin.setData = function (tit, no) {
    $c.util.getComponent('ipt_upSprtRoomNoTit').setValue(tit);
    $c.util.getComponent('ipt_upSprtRoomNo').setValue(no);
};

/**
 * @method
 * @name delValue
 * @description del Value 처리
 * @returns {void}
 * @hidden N
 */
scwin.delValue = function () {
    $c.util.getComponent('ipt_upSprtRoomNo').setValue('00000000000000');
    $c.util.getComponent('ipt_upSprtRoomNoTit').setValue('해당없음');
};
